import type { Product, Suggestion } from '../../../shared/quality.ts';

// Rule-based suggestions. NOT generated by Claude; the UI labels them as such.
export function demoSuggestions(p: Product): Suggestion[] {
  const out: Suggestion[] = [];
  const add = (x: Omit<Suggestion, 'status'>) => out.push({ ...x, status: 'pending' });
  const has = (n: string) => p.attributes.some((a) => a.name.toLowerCase() === n && a.value.trim());
  if (!p.shortDescription.trim()) add({ field: 'shortDescription', value: p.category ? `${p.name} (${p.category}).` : `${p.name}.`, source: 'inferred', confidence: 'low' });
  if (p.description.trim().length < 80) {
    const facts = [`${p.name}${p.category ? ` from our ${p.category} range` : ''}.`, ...p.attributes.filter((a) => a.value.trim()).map((a) => `${a.name}: ${a.value}.`)].join(' ');
    if (facts.length >= 80) add({ field: 'description', value: facts, source: 'existing_data', confidence: 'medium' });
    else add({ field: 'description', value: null, source: 'unknown', confidence: 'low', question: 'Not enough known facts to write a description. What are its key features?' });
  }
  if (!p.category.trim()) add({ field: 'category', value: null, source: 'unknown', confidence: 'low', question: 'Which category does this product belong to?' });
  if (!has('material')) add({ field: 'attribute', attributeName: 'Material', value: null, source: 'unknown', confidence: 'low', question: 'What material is it made from?' });
  if (!has('color')) add({ field: 'attribute', attributeName: 'Color', value: null, source: 'unknown', confidence: 'low', question: 'What color is it?' });
  if (!p.sku.trim()) add({ field: 'sku', value: null, source: 'unknown', confidence: 'low', question: 'What is the SKU for this product?' });
  if (!(Number(p.price) > 0)) add({ field: 'price', value: null, source: 'unknown', confidence: 'low', question: 'What is the price?' });
  if (!p.imageUrl) add({ field: 'imageUrl', value: null, source: 'unknown', confidence: 'low', question: 'Provide an image URL for this product.' });
  return out;
}
